index 765cadf..71553ca 100644
--- a/s2/shape.go
+++ b/s2/shape.go
@@ -283,8 +283,44 @@ var (
 	_ Shape = &Loop{}
 	_ Shape = &Polygon{}
 	_ Shape = &Polyline{}
